import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("DG to DJ (`935ca7f`) and DK to DL committed, waiting for her push. |", "DG to DJ (`935ca7f`), DK to DL (`f3d80d6`) and DM to DN committed, waiting for her push. |")
R("Students read 'the red note / key' (never 'coral'), and every notehead on every staff fits its space (DK, her 15:03).", "Students read 'the red note / key' (never 'coral'), and every notehead on every staff fits its space (DK, her 15:03). Each split Grades 2 and 3 room has a check-up on paper of its own (DM); the three melody rooms have none by design (their Workbook page is the writing). The Toolbox tab is gone (DN, her 21:41 on call 32): the teacher's tabs are Home · Chapters · Books · Printables · Practice; `?view=toolbox` lands on the Home.")
R("- Push: CX, CY to DC, DD to DF, DG to DJ, and DK to DL (five commits).", "- Push: CX, CY to DC, DD to DF, DG to DJ, DK to DL, and DM to DN (six commits).")
R("1. Own check-up items for the split Grades 2 and 3 rooms; then the Workbooks, fun first, floor by floor.", "1. Call 31: the dictionary cards (an earlier room's terms, underlined in a step's text and as chips on the opener; a neutral one-line definition, the room's picture, a way to the room, a quick check); two builds. Then call 33: Knowing Your Pieces to Grade 8 and diploma depth, then the attic's piano story. Then the Workbooks, fun first, floor by floor.")
io.open(md, 'w', encoding='utf-8').write(s)
h = io.open(hist, encoding='utf-8').read().split('\n')
idx = [i for i, l in enumerate(h) if l.startswith('| 757 |')]
assert len(idx) == 1 and not any(l.startswith('| 758 |') for l in h)
h[idx[0] + 1:idx[0] + 1] = [
 "| 758 | 2026-10-30 | **Own check-ups for the split Grades 2 and 3 rooms (Build DM; the board's next step).** Until now a split room's check-up on paper was the base's page with the other grade's parts hidden (numbered from the middle), and Scales, Grade 2's parts asked Grade 3 keys. Now each room's Workbook ends with a check-up of its own, parts A.. from item 1, in its own grade: Scales, Grade 2 (SCF_WB.chk2: black-key thumbs, thumbs meeting, mirror twins, chromatic from D, all Grade 2 keys), Scales, Grade 3 (chk3: C melodic minor's 6th and 7th up and down, mirror twins in the Grade 3 keys, chromatic from A and E♭, thumbs meeting in the Grade 3 keys by chapter 32's rule), Intervals, Grade 2 (H3_WB.chk2: name the interval; M, m or P), Chords and Cadences, Grade 3 (degree names, the chord and its inversion, perfect or plagal), Rhythm, Grade 2 (R2.chk2A/B: counts under semiquavers and triplets; R2_CHK2 how many), Rhythm, Grade 3 (chk3A/B: dotted quavers and the minim beat; R2_CHK3 beats in a bar; simple or compound); each with a CKP alternate for the floor checkpoint. The teacher copies' answer blocks and go-back pages follow; the split teacher and Workbook contexts show every part (the data is the room's own). CKP_ROOMS: scales-3 A C, harmony-2 B, harmony-3 A C, rhythm-2 B, rhythm-3 B C (one part each where two overflowed the checkpoint's page). The three melody rooms keep no check-up on paper: their Workbook page is the writing itself. Tests: dg782.js (the six rooms, 'AB' / 'ABC' / 'ABCD' pages), df781.js floors 3 and 4, and the full set. |",
]
h[idx[0] + 2:idx[0] + 2] = [
 "| 759 | 2026-10-30 | **The Toolbox tab goes (Build DN; her 21:41 'go with your recommendation' on call 32).** Checked first: of 316 activities, 263 open from their chapters, 15 from the Practice tab and the other 49 (the things to make, the Stories tools) from the rooms' 'Make your own' cards and the Home; none only from the Toolbox. The teacher's tabs are Home · Chapters · Books · Printables · Practice. `?view=toolbox` lands on the Home (`&sec=books` still on Books); a tool opened with ret=toolbox and a tool found with the Find button go back to the Home; the Home's one category that still sent people to the Toolbox (Practice, under Beside the piano) opens the Practice tab; a kit link still opens its kit and goes back to the Home. Kits are retired with the tab (a device's data stays). The Toolbox's Students button opened a view that no longer rendered (the dashboard took it over); the header's Dashboard link is the way. ToolboxTab stays in the code, unused. Test: dn789.js; chsweep, cy774, dd779. Also in this commit: research33-grade8.md, the syllabus check behind call 33 (theory ends at Grade 6; the theory co-requisites Grade 8 ← 4, Certificate ← 4, AMusA ← 5, LMusA ← 6; what a Grade 8 or diploma candidate needs that the drills lack). |",
]
io.open(hist, 'w', encoding='utf-8').write('\n'.join(h))
print('CLAUDE.md and CLAUDE-history.md updated (rows 758 to 759)')
